Here is a complete Rust project that ports your TypeScript cache to idiomatic Rust + Tokio, with TTL, LRU behavior, weak refs, async eviction loop, and ported tests.

### `Cargo.toml`
```toml
[package]
name = "tokio_lru_cache"
version = "0.1.0"
edition = "2021"

[dependencies]
linked-hash-map = "0.5"
tokio = { version = "1", features = ["rt-multi-thread", "macros", "time", "sync"] }

[lib]
name = "tokio_lru_cache"
path = "src/lib.rs"
```

---

### `src/lib.rs`
```rust
use linked_hash_map::LinkedHashMap;
use std::any::Any;
use std::sync::{Arc, Weak};
use std::time::{Duration, Instant};
use tokio::sync::{oneshot, Mutex};
use tokio::task::JoinHandle;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

pub type EvictCallback = Arc<dyn Fn(&str, EvictionReason) + Send + Sync>;

#[derive(Clone)]
pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<EvictCallback>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_millis(60_000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5_000),
            on_evict: None,
        }
    }
}

#[derive(Clone, Default)]
pub struct PartialCacheConfig {
    pub max_entries: Option<usize>,
    pub default_ttl: Option<Duration>,
    pub max_memory_bytes: Option<usize>,
    pub eviction_check_interval: Option<Duration>,
    pub on_evict: Option<EvictCallback>,
}

impl From<PartialCacheConfig> for CacheConfig {
    fn from(p: PartialCacheConfig) -> Self {
        let defaults = CacheConfig::default();
        Self {
            max_entries: p.max_entries.unwrap_or(defaults.max_entries),
            default_ttl: p.default_ttl.unwrap_or(defaults.default_ttl),
            max_memory_bytes: p.max_memory_bytes.unwrap_or(defaults.max_memory_bytes),
            eviction_check_interval: p
                .eviction_check_interval
                .unwrap_or(defaults.eviction_check_interval),
            on_evict: p.on_evict,
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct CacheStatsSnapshot {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct PutOptions {
    pub ttl: Option<Duration>,
    pub size: Option<usize>,
}

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
    weak_ref: Weak<()>,
    _strong_ref: Arc<()>,
}

pub struct LruCache<V> {
    entries: LinkedHashMap<String, CacheEntry<V>>, // oldest -> newest
    config: CacheConfig,
    current_memory: usize,
    stats: CacheStats,
}

pub type SharedLruCache<V> = Arc<Mutex<LruCache<V>>>;

impl<V: 'static> Default for LruCache<V> {
    fn default() -> Self {
        Self::new(PartialCacheConfig::default())
    }
}

impl<V: 'static> LruCache<V> {
    pub fn new(config: PartialCacheConfig) -> Self {
        Self {
            entries: LinkedHashMap::new(),
            config: config.into(),
            current_memory: 0,
            stats: CacheStats::default(),
        }
    }

    pub fn get(&mut self, key: &str) -> Option<&V> {
        let now = Instant::now();

        let is_expired = match self.entries.get(key) {
            Some(entry) => now > entry.expires_at,
            None => {
                self.stats.misses = self.stats.misses.saturating_add(1);
                return None;
            }
        };

